const { startServer, stopServer } = require('./server/index.js');
(async () => {
  const { port } = await startServer(8088);
  if (global.gc) global.gc();
  const initialHeap = process.memoryUsage().heapUsed;

  // Run 30 health and servers requests
  for (let i = 0; i < 30; i++) {
    await fetch('http://127.0.0.1:' + port + '/health').then(r => r.json());
    await fetch('http://127.0.0.1:' + port + '/api/servers').then(r => r.json());
  }

  // Run 5 stream resolution requests
  for (let i = 0; i < 5; i++) {
    await fetch('http://127.0.0.1:' + port + '/api/stream?tmdbId=27205&type=movie').then(r => r.json());
  }

  const finalHeap = process.memoryUsage().heapUsed;
  console.log('Initial heap (KB):', Math.round(initialHeap / 1024));
  console.log('Final heap (KB):', Math.round(finalHeap / 1024));
  console.log('Delta heap (KB):', Math.round((finalHeap - initialHeap) / 1024));

  await stopServer();
})();
